function stepCopy(id, detail) {
  const body = STEP_BODY[id];
  if (!body) throw new Error(`Missing specific tutorial text for ${id}`);
  return copy(
    { title: `Pruefe ${detail.de}`, body: body.de, expected: `${detail.de} ist am konkreten Bedienelement sichtbar.`, alt: `${detail.de} in der lokalen Plugin-Oberflaeche` },
    { title: `Check ${detail.en}`, body: body.en, expected: `${detail.en} is visible at the specific control.`, alt: `${detail.en} in the local plugin interface` },
    { title: `Revisa ${detail.es}`, body: body.es, expected: `${detail.es} es visible en el control especifico.`, alt: `${detail.es} en la interfaz local del plugin` },
    { title: `Verifiez ${detail.fr}`, body: body.fr, expected: `${detail.fr} est visible sur le controle cible.`, alt: `${detail.fr} dans l interface locale du plugin` }
  );
}

function read(id, route, selector, detail) {
  return step(id, route, selector, stepCopy(id, detail), { operations: [{ type: 'inspect', selector }], postconditions: [{ type: 'visible', selector }] });
}

function press(id, route, selector, detail, target = selector) {
  return step(id, route, selector, stepCopy(id, detail), { operations: [{ type: 'click', selector }], postconditions: [{ type: 'visible', selector: target }] });
}

// Legacy call sites use this name, but the visual guides must never fill or
// persist a setting.  They now inspect the field exactly as written.
function enter(id, route, selector, _value, detail) {
  return read(id, route, selector, detail);
}

